/**
 * spikes/lod/h12-ladder-math/lattice.ts
 *
 * Pure lattice math for H12 (rotation-free m^2 ladders) and H13's a7 control.
 * No DOM. Everything is expressed in PARENT-LOCAL world px with the parent hex
 * centred at the origin and parent hexSize = PARENT_SIZE.
 *
 * Eisenstein model: axial (a,b) -> complex a + b*w, w = e^(i*pi/3).
 * |a + b*w|^2 = a^2 + a*b + b^2 = the Loeschian norm K.
 *
 * A sublattice generated by g = (ga,gb) and its 60-degree rotation has index K(g),
 * linear scale sqrt(K), and rotation = arg(ga + gb*w). Rotation is exactly 0 only
 * when gb == 0, i.e. K = ga^2 is a perfect square AND the (m,0) generator was picked.
 */

export const PARENT_SIZE = 80; // world px, hex centre -> vertex (matches fixture HEX_SIZE)
const SQRT3 = Math.sqrt(3);

export interface LadderSpec {
  slug: string;
  ga: number;
  gb: number;
  /** ring-7 rosette instead of the full Voronoi tile (the shipped scheme) */
  rosetteRings?: number;
  /** the linear scale actually used for child hexSize; defaults to sqrt(K) */
  linearScaleOverride?: number;
  label: string;
}

export const LADDERS: Record<string, LadderSpec> = {
  ring7s15: { slug: 'ring7s15', ga: 15, gb: 0, rosetteRings: 7, linearScaleOverride: 15, label: 'shipped: ring-7 rosette @ linear 15' },
  m3: { slug: 'm3', ga: 3, gb: 0, label: 'm=3 (K=9)' },
  m5: { slug: 'm5', ga: 5, gb: 0, label: 'm=5 (K=25)' },
  m6: { slug: 'm6', ga: 6, gb: 0, label: 'm=6 (K=36)' },
  m13: { slug: 'm13', ga: 13, gb: 0, label: 'm=13 (K=169)' },
  a7: { slug: 'a7', ga: 2, gb: 1, label: 'aperture 7 (K=7, 19.1066 deg)' },
  // the OTHER representation of 169: 15^2 + 15*(-7) + (-7)^2 = 169. Same aperture, same
  // linear scale 13, but rotated. This is the generator whose tile is a ring-7 rosette.
  r7exact: { slug: 'r7exact', ga: 15, gb: -7, label: 'K=169 via (15,-7) — the rosette generator' },
};

// ------------------------------------------------------------------ hex primitives

/** flat-top axial -> world, hexSize s. Identical formula to HexGeometry.hexToWorld. */
export function hexPos(q: number, r: number, s: number): { x: number; y: number } {
  return { x: s * 1.5 * q, y: s * SQRT3 * (r + q / 2) };
}

/** inverse of hexPos, rounded to the nearest cell (cube rounding). */
export function worldToHexRounded(x: number, y: number, s: number): { q: number; r: number } {
  const q = (x * 2) / (3 * s);
  const r = y / (SQRT3 * s) - q / 2;
  return axialRound(q, r);
}

export function axialRound(qf: number, rf: number): { q: number; r: number } {
  const xf = qf;
  const zf = rf;
  const yf = -xf - zf;
  let rx = Math.round(xf);
  let ry = Math.round(yf);
  let rz = Math.round(zf);
  const dx = Math.abs(rx - xf);
  const dy = Math.abs(ry - yf);
  const dz = Math.abs(rz - zf);
  if (dx > dy && dx > dz) rx = -ry - rz;
  else if (dy > dz) ry = -rx - rz;
  else rz = -rx - ry;
  return { q: rx, r: rz };
}

export const hexRing = (q: number, r: number): number =>
  (Math.abs(q) + Math.abs(r) + Math.abs(q + r)) / 2;

/** point inside a flat-top hexagon of size s centred at the origin */
export function inHex(x: number, y: number, s: number): boolean {
  const ax = Math.abs(x);
  const ay = Math.abs(y);
  if (ay > (s * SQRT3) / 2 + 1e-12) return false;
  return SQRT3 * ax + ay <= SQRT3 * s + 1e-12;
}

export function hexCorners(s: number, thetaRad: number): Array<{ x: number; y: number }> {
  const out: Array<{ x: number; y: number }> = [];
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 180) * 60 * i + thetaRad;
    out.push({ x: s * Math.cos(a), y: s * Math.sin(a) });
  }
  return out;
}

// ------------------------------------------------------------------ the ladder

export interface Ladder {
  spec: LadderSpec;
  K: number;
  /** linear scale: parentSize / childSize */
  m: number;
  /** lattice rotation of the parent lattice relative to the child lattice, degrees */
  thetaDeg: number;
  thetaRad: number;
  childSize: number;
  /** offsets (child axial, relative to the parent's centre child) owned by a parent */
  childSet: Array<{ q: number; r: number }>;
  childKey: Set<string>;
  /** parent (Q,R) -> the child-axial index of its centre child */
  parentToChild(Q: number, R: number): { q: number; r: number };
  /** child axial -> owning parent (nearest centre, lexicographic tie-break) */
  parentOf(a: number, b: number): { Q: number; R: number; tie: boolean };
  /** child axial -> world px (rotation folded in so parents land on the unrotated grid) */
  childWorld(a: number, b: number): { x: number; y: number };
  /** rotated corner offsets for drawing a child hex */
  childCorners: Array<{ x: number; y: number }>;
}

export function buildLadder(spec: LadderSpec): Ladder {
  const { ga, gb } = spec;
  const K = ga * ga + ga * gb + gb * gb;
  // arg(ga + gb * e^{i pi/3})
  const gx = ga + gb * 0.5;
  const gy = gb * (SQRT3 / 2);
  const thetaRad = Math.atan2(gy, gx);
  const m = spec.linearScaleOverride ?? Math.sqrt(K);
  const childSize = PARENT_SIZE / m;

  const parentToChild = (Q: number, R: number): { q: number; r: number } => ({
    q: Q * ga + R * -gb,
    r: Q * gb + R * (ga + gb),
  });

  const cosT = Math.cos(-thetaRad);
  const sinT = Math.sin(-thetaRad);
  const childWorld = (a: number, b: number): { x: number; y: number } => {
    const p = hexPos(a, b, childSize);
    return { x: p.x * cosT - p.y * sinT, y: p.x * sinT + p.y * cosT };
  };

  const parentWorld = (Q: number, R: number): { x: number; y: number } => hexPos(Q, R, PARENT_SIZE);

  const parentOf = (a: number, b: number): { Q: number; R: number; tie: boolean } => {
    // M^-1 (a,b) with M = [[ga,-gb],[gb,ga+gb]], det = K
    const Qf = ((ga + gb) * a + gb * b) / K;
    const Rf = (-gb * a + ga * b) / K;
    const seed = axialRound(Qf, Rf);
    const cw = childWorld(a, b);
    let bestQ = seed.q;
    let bestR = seed.r;
    let bestD = Infinity;
    let tie = false;
    for (let dq = -2; dq <= 2; dq++) {
      for (let dr = -2; dr <= 2; dr++) {
        const Q = seed.q + dq;
        const R = seed.r + dr;
        const pw = parentWorld(Q, R);
        const d = Math.hypot(pw.x - cw.x, pw.y - cw.y);
        if (d < bestD - 1e-9 * PARENT_SIZE) {
          bestD = d;
          bestQ = Q;
          bestR = R;
          tie = false;
        } else if (Math.abs(d - bestD) <= 1e-9 * PARENT_SIZE) {
          tie = true;
          // deterministic tie-break: smallest (Q, R) lexicographically
          if (Q < bestQ || (Q === bestQ && R < bestR)) {
            bestQ = Q;
            bestR = R;
          }
        }
      }
    }
    return { Q: bestQ, R: bestR, tie };
  };

  // ---- the child set of parent (0,0)
  const childSet: Array<{ q: number; r: number }> = [];
  if (spec.rosetteRings != null) {
    const n = spec.rosetteRings;
    for (let q = -n; q <= n; q++) {
      for (let r = -n; r <= n; r++) {
        if (hexRing(q, r) <= n) childSet.push({ q, r });
      }
    }
  } else {
    const span = Math.ceil(m) + 2;
    for (let q = -span; q <= span; q++) {
      for (let r = -span; r <= span; r++) {
        const p = parentOf(q, r);
        if (p.Q === 0 && p.R === 0) childSet.push({ q, r });
      }
    }
  }
  const childKey = new Set(childSet.map((c) => c.q + ',' + c.r));

  return {
    spec,
    K,
    m,
    thetaDeg: (thetaRad * 180) / Math.PI,
    thetaRad,
    childSize,
    childSet,
    childKey,
    parentToChild,
    parentOf,
    childWorld,
    childCorners: hexCorners(childSize, -thetaRad),
  };
}

// ------------------------------------------------------------------ measurements

export interface Containment {
  samplesInParent: number;
  samplesInChildren: number;
  /** % of the parent hexagon's area covered by NO child of that parent */
  parentUncoveredPct: number;
  /** % of the child-union's area lying outside the parent hexagon */
  childOutsidePct: number;
  /** child-union area / parent area (1.0 for an exact tiling) */
  areaRatio: number;
  gridN: number;
}

export function measureContainment(L: Ladder, gridN = 1001): Containment {
  const half = PARENT_SIZE * 1.45;
  const step = (2 * half) / (gridN - 1);
  const cosT = Math.cos(L.thetaRad);
  const sinT = Math.sin(L.thetaRad);
  let inParent = 0;
  let inChild = 0;
  let both = 0;
  for (let i = 0; i < gridN; i++) {
    const x = -half + i * step;
    for (let j = 0; j < gridN; j++) {
      const y = -half + j * step;
      const p = inHex(x, y, PARENT_SIZE);
      // un-rotate into the child lattice frame
      const cx = x * cosT - y * sinT;
      const cy = x * sinT + y * cosT;
      const { q, r } = worldToHexRounded(cx, cy, L.childSize);
      const c = L.childKey.has(q + ',' + r);
      if (p) inParent++;
      if (c) inChild++;
      if (p && c) both++;
    }
  }
  return {
    samplesInParent: inParent,
    samplesInChildren: inChild,
    parentUncoveredPct: inParent ? (100 * (inParent - both)) / inParent : 0,
    childOutsidePct: inChild ? (100 * (inChild - both)) / inChild : 0,
    areaRatio: inParent ? inChild / inParent : 0,
    gridN,
  };
}

export interface BoundaryAgreement {
  perEdgeMeanPx: number[];
  meanPx: number;
  maxPx: number;
  meanPctOfParentSize: number;
  maxPctOfParentSize: number;
  segments: number;
}

/** outline of the child union: every child-hex edge with exactly one in-set owner */
export function childUnionOutline(L: Ladder): Array<[number, number, number, number]> {
  const counts = new Map<string, { n: number; seg: [number, number, number, number] }>();
  for (const c of L.childSet) {
    const ctr = L.childWorld(c.q, c.r);
    for (let k = 0; k < 6; k++) {
      const a = L.childCorners[k];
      const b = L.childCorners[(k + 1) % 6];
      const x1 = ctr.x + a.x;
      const y1 = ctr.y + a.y;
      const x2 = ctr.x + b.x;
      const y2 = ctr.y + b.y;
      const mx = (x1 + x2) / 2;
      const my = (y1 + y2) / 2;
      const key = mx.toFixed(4) + '|' + my.toFixed(4);
      const hit = counts.get(key);
      if (hit) hit.n++;
      else counts.set(key, { n: 1, seg: [x1, y1, x2, y2] });
    }
  }
  const out: Array<[number, number, number, number]> = [];
  for (const v of counts.values()) if (v.n === 1) out.push(v.seg);
  return out;
}

function distToSeg(px: number, py: number, s: [number, number, number, number]): number {
  const [x1, y1, x2, y2] = s;
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len2 = dx * dx + dy * dy;
  let t = len2 ? ((px - x1) * dx + (py - y1) * dy) / len2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

export function measureBoundary(L: Ladder, samplesPerEdge = 240): BoundaryAgreement {
  const segs = childUnionOutline(L);
  const corners = hexCorners(PARENT_SIZE, 0);
  const perEdgeMeanPx: number[] = [];
  let max = 0;
  for (let e = 0; e < 6; e++) {
    const a = corners[e];
    const b = corners[(e + 1) % 6];
    let sum = 0;
    for (let i = 0; i < samplesPerEdge; i++) {
      const t = (i + 0.5) / samplesPerEdge;
      const px = a.x + (b.x - a.x) * t;
      const py = a.y + (b.y - a.y) * t;
      let best = Infinity;
      for (const s of segs) {
        const d = distToSeg(px, py, s);
        if (d < best) best = d;
      }
      sum += best;
      if (best > max) max = best;
    }
    perEdgeMeanPx.push(sum / samplesPerEdge);
  }
  const mean = perEdgeMeanPx.reduce((a, b) => a + b, 0) / 6;
  return {
    perEdgeMeanPx: perEdgeMeanPx.map((v) => +v.toFixed(4)),
    meanPx: +mean.toFixed(4),
    maxPx: +max.toFixed(4),
    meanPctOfParentSize: +((100 * mean) / PARENT_SIZE).toFixed(4),
    maxPctOfParentSize: +((100 * max) / PARENT_SIZE).toFixed(4),
    segments: segs.length,
  };
}

// ------------------------------------------------------------------ the m=13 re-seat

export interface Reseat {
  ring7Count: number;
  m13Count: number;
  setsIdentical: boolean;
  onlyInRing7: number;
  onlyInM13: number;
  /** naive re-seat (keep child doc size, change the ladder): displacement per cell, world px */
  naiveMinPx: number;
  naiveMeanPx: number;
  naiveMaxPx: number;
  /** max displacement as a multiple of the shipped child cell size (80/15) */
  naiveMaxInChildCells: number;
  /** re-seat WITH the uniform 15/13 rescale of the child document */
  rescaledMaxPx: number;
  rescaleFactor: number;
}

export function measureReseat(): Reseat {
  const ring7 = buildLadder(LADDERS.ring7s15);
  const m13 = buildLadder(LADDERS.m13);
  const a = new Set(ring7.childSet.map((c) => c.q + ',' + c.r));
  const b = new Set(m13.childSet.map((c) => c.q + ',' + c.r));
  let onlyA = 0;
  let onlyB = 0;
  for (const k of a) if (!b.has(k)) onlyA++;
  for (const k of b) if (!a.has(k)) onlyB++;

  let min = Infinity;
  let max = 0;
  let sum = 0;
  let n = 0;
  let rescaledMax = 0;
  const s15 = PARENT_SIZE / 15;
  const s13 = PARENT_SIZE / 13;
  for (const c of ring7.childSet) {
    if (!b.has(c.q + ',' + c.r)) continue;
    const p15 = hexPos(c.q, c.r, s15);
    const p13 = hexPos(c.q, c.r, s13);
    const d = Math.hypot(p13.x - p15.x, p13.y - p15.y);
    if (d < min) min = d;
    if (d > max) max = d;
    sum += d;
    n++;
    // rescaled: multiply the whole child doc by 15/13 then place at 1/13
    const rp = { x: p15.x * (15 / 13), y: p15.y * (15 / 13) };
    const rd = Math.hypot(rp.x - p13.x, rp.y - p13.y);
    if (rd > rescaledMax) rescaledMax = rd;
  }
  return {
    ring7Count: ring7.childSet.length,
    m13Count: m13.childSet.length,
    setsIdentical: onlyA === 0 && onlyB === 0,
    onlyInRing7: onlyA,
    onlyInM13: onlyB,
    naiveMinPx: +(n ? min : 0).toFixed(5),
    naiveMeanPx: +(n ? sum / n : 0).toFixed(5),
    naiveMaxPx: +max.toFixed(5),
    naiveMaxInChildCells: +(max / s15).toFixed(4),
    rescaledMaxPx: +rescaledMax.toExponential(3).replace('e', 'e'),
    rescaleFactor: 15 / 13,
  };
}

// ------------------------------------------------------------------ in-page assertions

export interface LadderAsserts {
  childCount: number;
  expectedCount: number | null;
  countOK: boolean;
  roundTripOK: boolean;
  /** how many of this parent's children are equidistant from 2+ parent centres */
  tieCells: number;
  tieExamples: string[];
  rotationDeg: number;
  rotationIsZero: boolean;
}

export function assertLadder(L: Ladder): LadderAsserts {
  const expected = L.spec.rosetteRings != null ? 3 * L.spec.rosetteRings * (L.spec.rosetteRings + 1) + 1 : L.K;
  let roundTripOK = true;
  let ties = 0;
  const examples: string[] = [];
  for (const c of L.childSet) {
    const p = L.parentOf(c.q, c.r);
    if (L.spec.rosetteRings == null && (p.Q !== 0 || p.R !== 0)) roundTripOK = false;
    if (p.tie) {
      ties++;
      if (examples.length < 6) examples.push(`(${c.q},${c.r})`);
    }
  }
  return {
    childCount: L.childSet.length,
    expectedCount: expected,
    countOK: L.childSet.length === expected,
    roundTripOK,
    tieCells: ties,
    tieExamples: examples,
    rotationDeg: +L.thetaDeg.toFixed(6),
    rotationIsZero: Math.abs(L.thetaDeg) < 1e-12,
  };
}
